(function(){
function init(){
 const main=document.querySelector('.tp-main'),hero=document.querySelector('.tp-hero'),pairs=[...document.querySelectorAll('.tp-paired-section')];
 if(!main||!hero||pairs.length<2){requestAnimationFrame(init);return}
 if(main.dataset.redesigned)return;main.dataset.redesigned='true';
 const h=hero.querySelector('h1');h.innerHTML='<span class="rd-hero-line">The turnkey sportsbook</span><span class="rd-hero-line premium-gradient" data-gradient-filled="true">built for market leaders</span>';
 const art=hero.querySelector('.tp-hero-art');art.innerHTML='<img src="/_turnkey/premium-media/turnkey/platform-user.webp" alt="Turnkey Sportsbook platform">';
 const layer=main.querySelector('.tp-layer-story');if(layer)layer.style.display='none';
 const heroMotion=()=>{let r=hero.getBoundingClientRect(),shift=Math.max(0,Math.min(180,-r.top*.22));art.style.transform=`translateY(${-shift}px)`};window.addEventListener('scroll',heroMotion,{passive:true});heroMotion();const proof=main.querySelector('.tp-proof');if(proof)hero.append(proof);
 const platform=main.querySelector('.tp-platform');let rows=platform.querySelector('.tp-component-rows');platform.querySelector('h2').innerHTML='Technology that moves with<br><span class="premium-gradient" data-gradient-filled="true">your strategy</span>';
 if(rows){let intro=rows.querySelector('.tp-intro-components'),list=intro?.querySelector('.tp-disclosure-list');if(list){[...rows.querySelectorAll('.tp-component-row')].forEach((row,i)=>{let h=row.querySelector('h3'),p=row.querySelector('p');if(!h)return;let d=document.createElement('div');d.className='tp-disclosure';d.dataset.open='false';let title=document.createElement('h3'),button=document.createElement('button'),icon=row.querySelector('svg'),span=document.createElement('span'),body=document.createElement('div'),inner=document.createElement('div');button.type='button';button.setAttribute('aria-expanded','false');span.textContent=h.textContent;if(icon)button.append(icon);button.append(span);title.append(button);body.className='tp-disclosure-body';body.inert=true;if(p)inner.append(p);body.append(inner);d.append(title,body);button.addEventListener('click',()=>{let open=d.dataset.open!=='true';list.querySelectorAll('.tp-disclosure').forEach(item=>{let current=item===d&&open;item.dataset.open=String(current);item.querySelector('button').setAttribute('aria-expanded',String(current));item.querySelector('.tp-disclosure-body').inert=!current})});list.append(d)}); intro.querySelector('.tp-layer-slot')?.remove();let place=document.createElement('div');place.className='rd-placeholder';place.setAttribute('aria-hidden','true');intro.append(place);[...rows.children].filter(x=>x!==intro).forEach(x=>x.remove())}}
 platform.querySelectorAll('.tp-disclosure button').forEach((b,i)=>{b.dataset.step=String(i+1).padStart(2,'0')});
 const local=main.querySelector('.tp-local'),loccard=local?.querySelector('.tp-local-reference-card');if(loccard){let list=loccard.querySelector('.tp-disclosure-list');if(list){list.querySelectorAll('.tp-disclosure').forEach(d=>{d.dataset.open='true';let b=d.querySelector('button');if(b)b.setAttribute('aria-expanded','true');let body=d.querySelector('.tp-disclosure-body');if(body)body.inert=false});list.querySelectorAll('.tp-disclosure-body').forEach((body,i)=>{let ul=document.createElement('ul');ul.className='rd-local-list';(i===0?['Retail and digital channels','Content, betting activity, and engagement','Consistent brand experience']:['Market entry to ongoing operations','Local requirements','Consistent, scalable sportsbook infrastructure']).forEach(t=>{let li=document.createElement('li');li.textContent=t;ul.append(li)});body.append(ul)});loccard.replaceChildren(list);loccard.dataset.uiGlobe=""}}
 const cards=pairs.flatMap(x=>[...x.querySelectorAll('.tp-pair-card')]);if(cards.length===4){const names=['Personalised promotions','Relevant content','Real-time updates','Business growth'];const imgs=['competitive-promotions-76152bd7e96f.png','relevant-sports-content-1c6eee94d470.png','insight-to-action-cfe7ab505b95.png','built-for-next-1dd6e3e3b142.png'];let section=document.createElement('section');section.className='rd-tools';section.dataset.glowWeights='0.08,0.18';section.innerHTML='<div class="rd-sticky"><header><p class="tp-eyebrow">ALL YOU NEED</p><h2>The tools to engage players<br><span>and grow your business</span></h2></header><div class="rd-grid"><nav aria-label="Product benefits"></nav><div class="rd-art"></div><div class="rd-copy"></div></div></div>';let nav=section.querySelector('nav'),visual=section.querySelector('.rd-art'),copy=section.querySelector('.rd-copy');cards.forEach((card,i)=>{let button=document.createElement('button');button.type='button';button.textContent=names[i];button.addEventListener('click',()=>window.scrollTo({top:section.getBoundingClientRect().top+window.scrollY+i*(section.offsetHeight-innerHeight)/4+10,behavior:'smooth'}));nav.append(button);let image=document.createElement('img');image.style.setProperty('--index',i);image.src='/_turnkey/premium-media/turnkey/'+imgs[i];image.alt=names[i];visual.append(image);let panel=document.createElement('div');let text=card.querySelector('.tp-pair-copy');panel.append(text.querySelector('h3').cloneNode(true),text.querySelector('.tp-body').cloneNode(true));copy.append(panel)});pairs[0].before(section);pairs.forEach(x=>x.remove());let buttons=[...nav.children],images=[...visual.children],panels=[...copy.children],last=-1;function update(){let r=section.getBoundingClientRect(),distance=Math.max(1,section.offsetHeight-innerHeight),progress=Math.max(0,Math.min(.999,-r.top/distance)),i=Math.floor(progress*4);if(i!==last){last=i;buttons.forEach((e,j)=>{e.classList.toggle('active',i===j);e.setAttribute('aria-current',i===j?'true':'false')});images.forEach((e,j)=>e.classList.toggle('active',i===j));panels.forEach((e,j)=>e.classList.toggle('active',i===j))}section.style.setProperty('--progress',String((i+1)/4));section.style.setProperty('--step',String(i))}window.addEventListener('scroll',update,{passive:true});window.addEventListener('resize',update);update()}
}
requestAnimationFrame(init);
})();
